    faq_q_bag_examples_list: "Ce exemple sunt în Geanta mea?",
    faq_a_nm_me1_guide: "Sky – personajul tău în New Me, în prima formă (Sky 1). Prima dată, imediat după înscriere, se deschide un portal de lumină, cu scântei de jur împrejur, iar Sky iese zburând din el, explică în câteva atingeri ce urmează și apoi rămâne lângă fiecare întrebare: cât timp se aleg mesele, scrie cu tine în cartea sa, iar o atingere pe sfatul său arată altul. La final, Sky sărbătorește cu tine și te ia într-un tur scurt – iar când turul se termină, mai are un mic moment cu tine. Dacă pleci la jumătate – din întrebări sau din tur –, data viitoare Sky se bucură să te vadă și te întreabă dacă vrei să continui din același loc.",
