    faq_a_shop_holidays: "În Lista de Cumpărături, atinge cadoul: apar în ordine sărbătorile țării tale (cea din Setări), cu datele lor – calculate singure în fiecare an. Atinge o sărbătoare pentru o listă gata făcută cu ce cumpără lumea pentru ea; totul e selectat (în afară de ce e deja pe lista ta), debifează ce nu-ți trebuie și atinge „Adaugă pe listă”. Cu două săptămâni înainte de o sărbătoare, un card mic apare în partea de sus a listei; ✕ îl ascunde până la următoarea sărbătoare.",
    faq_q_shop_holidays: "Cum funcționează „Ce cumpărăm de sărbătoare”?",
    shop_hol_add: "Adaugă pe listă ({n})",
    shop_hol_added: "Adăugate pe listă: {n}",
    shop_hol_btn: "Ce cumpărăm de sărbătoare",
    shop_hol_items_title: "{holiday} – ce cumpărăm?",
    shop_hol_not_now: "Nu acum",
    faq_a_shop_delivery: "În Lista de Cumpărături, atinge camionul: alege ce e în livrare (totul e selectat), când ajunge – azi, mâine sau altă zi – și la ce oră (dimineață, prânz, seară sau „Altă oră…” pentru orele tale). Produsele acelea trec pe un card „Pe drum” în partea de sus a listei, cu ziua și orele. Când vine ziua, „A ajuns livrarea?” apare în Ziua Mea (iar cardul are „A ajuns?”). Dacă a ajuns tot, ele trec la „De cumpărat din nou”. Dacă lipsește ceva, atinge ce n-a ajuns și revine direct pe listă.",
    faq_a_shop_departments: "Lista se aranjează singură pe raioanele din supermarket – fructe și legume, pâine, lactate și ouă, carne și pește, băcănie, congelate, băuturi, gustări, curățenie, îngrijire, bebeluși și animale de companie – ca să treci prin culoare în ordine. Raionul e recunoscut după numele produsului. Dacă un produs a ajuns în locul greșit, atinge-l și alege-i raionul, sau „Altul…” ca să scrii tu unul.",
    faq_a_shop_share_qty: "Da. Lângă fiecare produs, + adaugă încă unul (×2, ×3…) și − scoate unul. Butonul de distribuire din partea de sus a Listei de Cumpărături trimite toată lista, frumos aranjată pe raioane, pe WhatsApp, pe email sau ca o copie.",
    faq_a_shop_two_buttons: "Amândouă înseamnă „cumpărat”. ✕ e pentru ceva ce cumperi o singură dată – iese de pe listă (și așteaptă în arhiva 🗑️ în caz că a fost o greșeală). ↺ e pentru lucrurile pe care le cumperi iar și iar – ies de pe listă și așteaptă în „De cumpărat din nou”: îl deschide butonul mic ↺ de lângă coșul de gunoi, în partea de jos a listei, iar o atingere acolo pune un produs înapoi pe listă. Din „Editează”, dinăuntru, poți scoate un produs. Când adaugi un produs, ce ai mai cumpărat înainte apare ca sugestie, iar dacă e deja pe listă, devine pur și simplu ×2 în loc de un al doilea rând.",
    faq_q_shop_delivery: "Cum funcționează „Am comandat cu livrare”?",
