    nm_demo_saved_2: "Iaurt cu granola și fructe",
    nm_demo_title: "Cum funcționează o schimbare",
    faq_a_new_me_challenge_journal: "Când se termină o provocare – mare, mini sau provocarea săptămânii –, la sărbătorire apare butonul 📝 Cum a fost?, care deschide o pagină în jurnalul provocărilor: cum te-ai simțit (cinci fețe), ce a ajutat, ce a fost greu și ce iau cu mine mai departe – nimic nu e obligatoriu și poate aștepta și pentru mai târziu. Jurnalul este un diamant în rucsacul fermecat: fiecare provocare încheiată, cu data ei și ce s-a scris, cea mai nouă prima – atinge una ca s-o citești, s-o editezi sau s-o distribui (se distribuie doar ce e pe pagină). O provocare încheiată primește și o medalie la realizări, la „Provocări pe care le-am terminat”. Jurnalul provocărilor este separat de jurnalul obișnuit.",
