    nm_chj_take: "Ce iau cu mine mai departe?",
    nm_chj_title: "Jurnalul provocărilor",
    nm_chj_write: "Scrie cum a fost",
    nm_swap_time: "Ora",
    faq_a_ai_reminder_in_text: "Da – scrie-l împreună cu sarcina, de exemplu „mâine la 17:00 de ridicat coletul, cu un memento cu o oră înainte”. Mementoul se salvează chiar pe sarcină: cu o oră înainte, cu o jumătate de oră, cu o zi înainte și așa mai departe, iar „amintește-mi” fără oră înseamnă cu 10 minute înainte. Un memento scris în text are prioritate față de câmpul de memento din aceeași fereastră.",
    faq_q_ai_reminder_in_text: "Pot cere asistentului AI un memento în aceeași cerere?",
    myday_meals_all_done: "Toate mesele de azi sunt bifate 🍽️",
    nm_tour_week_text: "O provocare mică pentru săptămână. ✓ în fiecare zi – iar la final, o cheie.",
    books_home_chip: "{title} · pag. {page}",
    books_home_of: "din {total}",
    books_home_off_toast: "Cartea a plecat de pe ecranul principal",
    books_home_on_toast: "Cartea este pe ecranul principal 📖",
    books_home_pin: "Pe ecranul principal",
    books_home_q: "La ce pagină sunt?",
    books_home_save: "Salvează",
    faq_a_books_home_chip: "Da. În Colțul de lectură, pe cardul unei cărți pe care o citești, atinge 📌 Pe ecranul principal. Sub salut, pe ecranul principal, apare un buton mic cu cartea și pagina – atinge-l, scrie numărul noii pagini și salvează, iar progresul este înregistrat (și în Colțul de lectură). Încă o atingere pe 📌 o scoate. Pot fi acolo mai multe cărți deodată – câte un buton pentru fiecare – la fel pe fiecare dispozitiv.",
    faq_a_new_me_week_challenge: "O provocare mică pentru o săptămână, pe care o alegi tu. În hol este un card mare: „La ce ai vrea să lucrezi săptămâna aceasta?” – atinge-l, alege un domeniu (cu mine, cu ceilalți, să învăț și să cresc, calm, pași mici de curaj, casă și rutină) și o provocare, și alege când începe. Aceleași provocări se găsesc și pe ecranul provocărilor, la 🌱 Dezvoltare personală. În fiecare zi pui un ✓ pe card (o zi liberă pe săptămână), iar fiecare săptămână încheiată aduce o cheie nouă pentru lumea secretă. „Să citesc 2 pagini pe zi” se bifează singură din paginile înregistrate în Colțul de lectură. Când săptămâna se termină, 📌 Păstreaz-o ca sarcină zilnică o adaugă în Rutina Mea la ora aleasă, cu un ✓ în fiecare zi. Rulează o singură provocare a săptămânii odată; provocările mari și mini continuă alături de ea.",
    faq_a_room_genie: "Pe veranda cu vedere la mare, o atingere pe lampa lui Aladin scoate spiritul pădurii – și începe o conversație: care e dorința ta (ce ai vrea să schimbi în viață), cum va fi când se împlinește, ce e greu pe drum și cum poate fi transformată situația de acum în ceva bun. Apoi cât timp va dura aproximativ, un prim pas mic și încă doi, și un „dacă… atunci…” pentru când va fi greu. La final apare toată dorința pas cu pas și poate deveni obiectiv în Obiectivele Mele (pașii devin repere pe potecă, cu o dată după timpul ales; acolo se poate schimba orice) sau poate fi salvată în jurnal – și apoi spiritul își ia rămas-bun. Nu se salvează nimic dacă nu alegi una dintre ele. De la a doua vizită, spiritul întreabă mai întâi dacă ai vrea să schimbi și altceva în viața ta: da – aceeași conversație; nu acum – o reamintire să atingi obiectivele deja stabilite. Spiritul iese o dată pe zi: după ce o dorință a fost salvată (sau după „Nu acum”), se odihnește până mâine. Întrebările urmează o metodă cunoscută de a transforma o dorință într-un plan: dorință, rezultat, obstacol și plan.",
    faq_q_books_home_chip: "Pot vedea cartea și pagina pe ecranul principal?",
    faq_q_new_me_week_challenge: "Ce este provocarea săptămânii?",
    faq_q_room_genie: "Ce face duhul lămpii?",
