    nm_me_on_screen: "Pe ecran",
    faq_a_new_me_game: "În New Me butoanele jocului rămân mereu în același loc – în hol, în camera secretă și peste tot în pădure; se schimbă doar pictura din mijloc. Sus: ziua din călătorie, cheile, seria și energia de azi (cât s-a mâncat din plan), iar dedesubt următoarea misiune – următoarea masă la ora ei (o atingere o deschide, cu ✓ Am mâncat). Pe margine: toată ziua, provocări și călătoria mea, iar lângă ele provocarea săptămânii – cele 7 zile ale ei și un ✓ pentru azi. Jos: rucsacul fermecat (tot New Me – harta lumii, călătoria mea, cumpărături, realizări, jurnalul provocărilor, măsurători, poze, calendarul lunar, tabelul zilnic, mementouri, meniul PDF și setări; se deschide ca ecran separat). Harta lumii, primul lucru din rucsac, arată fiecare loc din pădure – atinge un loc ca să mergi acolo; pe un loc încuiat scrie de câte chei are nevoie. Sky este personajul tău pe poteca din pădure: începe ca Sky 1, după câteva provocări (4 chei) crește în Sky 2, iar spre final (9 chei) în Sky 3 – cu o transformare pe care o vezi petrecându-se. Atinge-l pe Sky ca să vezi toate etapele – orice etapă deja atinsă poate fi aleasă din nou, așa că una anterioară poate reveni. Sky plutește – se trage cu degetul sau cu mouse-ul, iar intrarea pe care o atinge se deschide (la una blocată scrie câte chei lipsesc). Sky vine cu tine și în fiecare cameră și loc și plutește acolo unde îl lași: trage-l oriunde și trage inelul strălucitor de sub el ca să-l rotești complet; privește în direcția în care se mișcă (pe calculator: săgețile îl mișcă, Q și E îl rotesc). În hol, mica 🏠 de sub bara de sus revine la ecranul principal; în fiecare cameră și loc, butonul din același colț revine în hol.",
    faq_q_new_me_game: "Cum funcționează butoanele jocului, harta lumii și Sky?",
