    faq_a_new_me_menu_build: "Mai întâi chestionarul întreabă ce mese iei și când (2 mese + o gustare, 2 mese + o cină ușoară sau ambele) și dacă seara e ceva – de mâncat sau de băut, ce anume și la ce oră. La „2 mese + o gustare”, mesele sunt prânzul (11:30) și cina (19:00), iar gustarea la 16:00. Apoi apar toate opțiunile pentru aceste mese. Alege până la 2 favorite pentru fiecare masă – în meniu scrie „asta sau aia”. La unele opțiuni (pita cu cremă, fulgi de porumb cu lapte, ceva ușor) alegi până la 3 lucruri care îți plac, fiecare în porția lui, iar în meniu scrie „asta sau aia sau aia”; caloriile urmează ce ai ales. Cafeaua și băuturile funcționează la fel. Fiecare alegere e echilibrată, așa că ziua dă exact 1.300 sau 1.500. Ca să schimbi oricând: ⚙️ Setări → 🍽️ Construiește-ți meniul sau „Alege până la 3 care îți plac” pe cardul mesei.",
