    faq_a_myday_water_toggle: "Da. Paharul cu apă din Ziua Mea (cu + pentru încă un pahar) apare implicit. Pentru a-l ascunde, dezactivează „Afișează apa în Ziua Mea” în Setări > Personalizare și calendar. Nu se șterge nimic – Monitorizarea Apei continuă să funcționeze, iar la reactivarea comutatorului paharul revine.",
