    myday_water_toggle_label: "Afișează apa în Ziua Mea",
    faq_a_routine_newme_sync: "Cu New Me, ⚙️ din Rutina Mea are un comutator „Sincronizare cu New Me”. Pornit (implicit), mesele de azi din New Me apar în Ziua Mea și în Rutina Mea – în locul meselor din rutină care au fost ascunse. Oprit, mesele New Me ies din amândouă și rutina revine exact cum era. Nu se șterge nimic – repornirea aduce totul înapoi și întreabă ce mese din rutină să ascunzi.",
