    faq_a_food_list_languages: "Lista de alimente încorporată a pornit de la mâncăruri israeliene și numele lor în ebraică. În toate celelalte limbi fiecare aliment apare cu numele său în engleză, iar căutarea găsește orice nume în engleză pe care îl cunoaște (de exemplu 'broth' găsește Clear soup); alimentele care au doar nume în ebraică nu apar acolo. Orice nu e în listă poate fi scris pur și simplu cu cuvintele tale – estimarea cu AI funcționează în orice limbă.",
    faq_q_food_list_languages: "De ce lista de alimente arată nume în engleză, și mai puține alimente, în limba mea?",
    settings_copyright_line: "© 2026 toate drepturile rezervate. aplicație dezvoltată de eden zabari.",
    workout_ready_replace_btn: "Înlocuiește",
    faq_a_sport_workout_ai: "În „Antrenamentele mele” → ⋯ → „Plan cu AI” (și, când tabelul e gol, și pe dala de lângă planurile gata făcute). Răspunde din câteva atingeri – de câte ori pe săptămână, când, loc, nivel și obiectiv, aproape toate au și „Altceva” – și, dacă vrei, adaugă un rând liber, cum ar fi un genunchi sensibil sau 5 km de alergat până la vară. AI-ul construiește o săptămână întreagă: tipuri de antrenament, zile, ore, durată, intensitate, exerciții și zile de odihnă. Înainte să se salveze ceva apare o previzualizare: „Pune-l în tabelul meu” (în locul tabelului sau în plus), „Altă propunere” (de până la 3 ori) sau „Schimbă răspunsurile”. Planul e moderat intenționat, iar dacă pomenești o durere sau o accidentare primești variante blânde și sfatul de a consulta un specialist. Folosește aceeași cotă AI ca programul și rutina: de 5 ori gratuit și de 60 de ori pe lună cu Premium.",
    faq_q_sport_workout_ai: "Cum creez un plan de antrenament cu AI?",
