    workout_ai_working: "Planul se pregătește…",
    faq_a_sport_workout_jar: "Fiecare tip de antrenament are steaua lui colorată – alergarea roz, mersul verde, înotul albastru și așa mai departe. Fiecare antrenament înregistrat săptămâna aceasta, din tabel sau separat, își lasă steaua în borcanul din partea de sus a „Antrenamentelor mele”, iar borcanul se umple până la obiectivul săptămânal (atinge-l ca să schimbi obiectivul). Când atingi obiectivul, borcanul strălucește. Borcanul mic de alături numără câte săptămâni la rând l-ai umplut.",
    faq_q_sport_workout_jar: "Ce sunt stelele colorate și borcanul din „Antrenamentele mele”?",
    faq_a_sport_workout_gcal: "Da – în ⋯ → Google Calendar (după ce conectezi Google Calendar din Setări). Fiecare antrenament cu oră devine un eveniment care se repetă în fiecare săptămână în zilele lui, iar schimbările din aplicație îl actualizează. Mementourile vin doar din aplicație, așa că Google nu adaugă altele, iar antrenamentele nu apar niciodată de două ori în aplicație. O nouă atingere scoate din Google Calendar doar antrenamentele.",
    faq_q_sport_workout_gcal: "Pot apărea antrenamentele mele în Google Calendar?",
