    workout_gcal_off_toast: "Antrenamentele au fost scoase din Google Calendar",
    workout_gcal_on_toast: "Antrenamentele tale sunt în Google Calendar",
    faq_a_sport_workout_reminder: "Da – într-un antrenament, Memento: cu 10 minute, 30 de minute sau o oră înainte, ori un timp personalizat (antrenamentul are nevoie de o oră). Sună ca celelalte mementouri, o singură dată și într-un singur loc: în aplicație dacă e deschisă, altfel pe telefon. „Gata” înregistrează antrenamentul în istoric, iar „Încă nu” îți amintește din nou peste 5 minute.",
    faq_q_sport_workout_reminder: "Pot primi un memento înaintea unui antrenament?",
    workout_reminder_30min: "Cu 30 de minute înainte",
    workout_reminder_label: "Memento",
    workout_reminder_need_time: "Adaugă o oră ca să primești un memento",
    faq_a_sport_workout_share: "În ⋯ → Distribuie, săptămâna devine o imagine cu efect de sticlă în culorile temei tale, cu un link discret spre aplicație (pe telefon merge direct în meniul de distribuire, pe calculator imaginea se salvează). ⋯ → PDF de tipărit deschide o pagină curată cu toată săptămâna și o căsuță de bifat lângă fiecare antrenament și exercițiu – alege „Salvează ca PDF” sau tipărește. Planul apare și în raportul de date din Setări, la Sport.",
    faq_q_sport_workout_share: "Cum îmi distribui sau tipăresc săptămâna de antrenament?",
    share_image_saved: "Imaginea a fost salvată – o poți atașa",
    share_save_image: "Salvează imaginea",
    workout_pdf_btn: "PDF de tipărit",
    workout_share_btn: "Distribuie",
    faq_a_sport_workout_board: "În ⋯ → Panou săptămânal fiecare zi e o coloană: trage un antrenament în altă zi (pe telefon, ține apăsat mai întâi). Într-un antrenament, „Și în Rutina Mea” îl pune în rutina ta la ora și în zilele lui, iar schimbările rămân sincronizate în ambele sensuri; dintr-un element din Rutina Mea, „Adaugă la antrenamentele mele” face invers. Un ✓ în oricare dintre ele contează în ambele, iar în Ziua Mea apare o singură dată – în eticheta de lângă apă.",
    faq_q_sport_workout_board: "Cum mut un antrenament în altă zi și îl leg de Rutina Mea?",
    routine_in_workouts_btn: "Deschide în antrenamentele mele",
