    workout_moved: "Mutat pe {day}",
    workout_routine_need_time: "Adaugă o oră ca să-l pui în Rutina Mea",
    workout_routine_toggle: "Și în Rutina Mea",
    workout_view_board: "Panou săptămânal",
    workout_view_timeline: "Cronologie",
    faq_a_sport_workout_plan: "În Urmărire Antrenamente, la „Antrenamentele mele”: + Antrenament – tip, zile, oră, durată, intensitate și loc (și „Altceva”). Antrenamentele de forță, funcționale și de înot pot avea o listă de exerciții, iar „Odihnă” marchează o zi de odihnă. Poți porni și de la un plan gata făcut. Antrenamentul de azi apare mare, cu toată săptămâna dedesubt; ✓ îl înregistrează în istoricul antrenamentelor împreună cu intensitatea. În ⋯ stabilești un obiectiv săptămânal (antrenamente sau minute) – fiecare antrenament făcut își lasă steaua în borcan.",
    faq_a_sport_workout_today: "În Ziua Mea, lângă apă, o mică etichetă arată antrenamentul de azi – o atingere deschide detaliile, ✓ și ▶. ▶ pornește un cronometru care continuă în eticheta de pe ecranul principal, iar „Termină” înregistrează antrenamentul cu timpul real. Dacă în New Me rulează provocarea „Două săptămâni de mișcare”, un antrenament înregistrat se numără acolo singur.",
