    faq_a_new_me_magic_themes: "Cinci teme strălucitoare incluse în New Me: Pădurea fermecată, Praf de stele, Zâna trandafirilor, Aurora magică și Amurg auriu. Alege una în New Me (⚙️ Setări > Culori) sau în Setări > Aspect și afișaj, iar o pensulă cu sclipici pictează ecranul în tema aleasă. O temă magică adaugă sclipici în toată aplicația și la fiecare atingere. Poți reveni oricând la orice altă temă.",
