    apptour_focus_text: "Totul se dă la o parte în afară de singurul lucru de acum – cu un ✓ mare. Apoi apare următorul.",
    apptour_m_presets_text: "Mesele tale salvate într-un singur loc: căutare, folosite recent, după momentul zilei – iar ＋ adaugă una la ziua de azi.",
    apptour_night_text: "🌙 întunecă toată aplicația; ☀️ aduce ziua înapoi.",
    apptour_noteline_text: "Scrie și atinge ➤ – se salvează în notițele tale. 📝 de la început trece la 🛒 cumpărături sau la 🍎 o masă salvată.",
    apptour_search_text: "Notițe, cumpărături, calendar, rețete, caiete, obiective, tabele și cărți – o singură căutare găsește tot.",
    faq_a_new_me_ai_menu: "Înainte de meniu, chestionarul întreabă ce mese iei și când (2 mese + o gustare, 2 mese + o cină ușoară sau ambele), dacă seara mănânci ceva mic și la ce oră, ce nu mănânci și cum bei cafeaua sau ceaiul. Apoi AI creează 3 opțiuni pentru fiecare masă – fiecare cât partea ei din zi, așa că ziua dă în continuare exact 1.300 sau 1.500 – și idei de băuturi, salvate ca băuturile tale fixe. Alege până la 2 favorite pe masă; opțiunile din meniul original sunt chiar dedesubt, iar în 🔄 Schimbă apar după meniul tău personal. 🔄 Alte opțiuni creează un set nou (de 3 ori pe chestionar). Ca să schimbi răspunsurile sau să creezi un meniu nou oricând: ⚙️ Setări → ✨ Meniu personal (AI).",
