    apptour_s_gcal_inside_text: "Conectează Google Calendar o singură dată, iar evenimentele și sarcinile rămân sincronizate în ambele sensuri.",
    apptour_s_menu_text: "Aici e tot ce poți ajusta, în cinci grupuri. Hai să le deschidem 👇",
    apptour_skip_part: "Sari peste această parte",
    apptour_start: "Începe turul",
    nm_sales_premium: "Include tot Premium",
    nm_unlock_premium: "Și tot Premium s-a deblocat.",
    settings_sub_status_newme: "Premium este inclus în New Me-ul tău.",
    room_back_to_shelf: "La raft",
    faq_a_new_me_day_total: "Fiecare zi ajunge exact la plan: mesele, cam 150 de calorii pentru cafea și băuturi în timpul zilei și ce s-a ales pentru seară – ceva mic de mâncat sau ceva de băut. Pentru seară, alege până la 3 care îți plac (de exemplu o banană, un iaurt sau 2 pătrățele de ciocolată neagră; ori ceai de plante, ceai cu puțin lapte sau lapte cald), iar caloriile lor se iau din mese. Fiecare alegere se echilibrează singură: o opțiune mai mică sau mai mare, o masă scoasă, micul dejun mic și masa mică ce vine cu el, ori seara – diferența se adaugă la mese sau se scade din ele, la fiecare după mărimea ei, iar sub fiecare masă scrie cât (+ sau −) și ce se poate adăuga sau lăsa deoparte. O masă deja bifată rămâne cum a fost înregistrată. În chestionar, fiecare masă își arată ajustarea, iar o căsuță mică arată mesele, băuturile, seara și totalul. Ai poftă de altceva în ziua aceea? Păstrează totalul la aceleași calorii sau mai puțin.",
    faq_q_new_me_day_total: "Cum ajunge o zi New Me exact la 1.300 / 1.500 și unde se socotesc băuturile?",
