    nm_less_ideas_l: "o felie de pâine și o lingură de tahini mai puțin, sau jumătate din carbohidrați",
    nm_less_ideas_m: "o felie de pâine mai puțin, sau o lingură mai puțin de tahini",
    nm_less_ideas_s: "o linguriță mai puțin de ulei sau tahini",
    nm_less_line: "{n} calorii în masa aceasta, ca ziua să ajungă la {plan} – de exemplu {ideas}",
    nm_less_line_late: "{n} calorii în masa aceasta, pentru ceva mic la {time} – de exemplu {ideas}",
    nm_swap_balanced: "{n} calorii împărțite între mese, ca ziua să ajungă la {plan}",
    books_quotes_chip: "Citate",
    faq_a_book_quotes: "Pe raftul din camera secretă (Citate) sau prin eticheta mică 💬 Citate din Colțul de lectură – e aceeași listă. Atinge „+ Citat”, scrie fraza și alege cartea din Colțul de lectură sau scrie alt titlu cu „✏️ Altele”; autorul e opțional. ✏️ modifică un citat, iar 🗑️ îl șterge. Citatele sunt semne de carte prin care glisezi – 🎨 de sus schimbă în fotografii sau un perete de carduri.",
    faq_a_room_wish_jar: "Pe raftul din camera secretă e un borcan de sticlă pentru vise. Atinge borcănelul de pe raftul de sus (sau Raftul > Borcanul dorințelor) și scrie cum ai vrea să arate viața ta – oricât de nebunește, fără bine sau rău. Fiecare dorință se împăturește într-un bilețel și cade în borcan. „Trage un bilețel” deschide unul la întâmplare, iar fiecare bilețel se poate deschide și separat. Din a doua oară când deschizi aceeași dorință, o poți transforma într-un obiectiv și împărți în pași mici. O dată pe săptămână apare blând un bilețel cu una dintre dorințele tale – fără presiune, doar o amintire a direcției tale.",
    faq_q_book_quotes: "Unde păstrez citatele din cărțile pe care le-am iubit?",
