    faq_a_saved_meals_page: "Mesele salvate au o pagină a lor: Nutriție și Măsurători > ⭐ Mese salvate (sau ⭐ din meniu). Căutarea de sus găsește o masă după nume sau ingredient, „Folosite recent” arată ce ai adăugat în ultima vreme, iar filele (Mic dejun, Prânz, Cină, Supe…) arată fiecare moment al zilei. „+ Azi” adaugă o masă în Jurnalul Zilnic de Alimentație de azi, în următorul loc liber. Atinge o masă ca s-o modifici sau s-o ștergi, iar ＋ de sus adaugă una nouă.",
