    faq_a_notes_sticky_look: "Notițele sunt o listă scurtă de carduri de sticlă – 🎨 din partea de sus a Notițelor schimbă aspectul tuturor Notițelor: lista, butoanele zilelor de sus și fereastra în care se scrie o notiță – sticlă, listă simplă, fișe sau bandă washi. O notiță trasă își păstrează exact aspectul și culoarea ei. Atinge textul unei notițe ca s-o deschizi – acolo o poți modifica, îi poți schimba culorile și poți vedea când a fost scrisă ultima dată. Atinge ○ când e gata, iar × o mută în arhivă (🗑️ din josul listei o aduce înapoi). Trage-o de ⠿ ca să schimbi ordinea, sub „Mai târziu” sau pe o zi de sus. ! marchează o notiță ca urgentă – urcă ușor până în primele rânduri, cu o etichetă mică „Urgent”; încă o atingere scoate marcajul.",
    faq_q_notes_sticky_look: "Cum deschid, modific sau elimin o notiță?",
    note_to_archive_btn: "Mută în arhivă",
    faq_a_routine_clash: "Dacă la ora aceea, în aceleași zile, există deja ceva, apar două variante: „Înlocuiește” – elementul nou ia ora aceea și alegi altă oră pentru cel care era acolo (când editezi un element existent, se propune ora lui anterioară, așa că cele două pur și simplu fac schimb), sau „Amândouă” – rămân amândouă la aceeași oră, unul sub altul. Dacă zilele diferă (de exemplu unul duminică–joi și celălalt vineri), nu se întreabă nimic.",
