    routine_clash_title: "La {time} există deja: {title}",
    faq_a_new_me_coffee: "Sub meniul de azi e un rezumat scurt: câte calorii au împreună toate mesele zilei, cât a mai rămas pentru cafea și băuturi, și butoane pentru cafeaua și băuturile alese – o atingere o adaugă la Băuturi. În „Alege până la 3 care îți plac” de sub butoane (și în chestionar) alegi ce apare: apă / apă carbogazoasă, ceai de plante, o băutură diet, neagră / americano (~5), ceai cu puțin lapte (~25), cafea pe bază de apă cu până la 100 ml lapte sau băutură vegetală (~50), ciocolată caldă light, lapte cald sau cafea obișnuită / latte (~120).",
