    faq_a_recipe_examples: "Sub rețetele tale sunt rețete exemplu: mic-dejunuri, salate, supe, feluri principale, garnituri, gustări, deserturi și mâncăruri vegane, fiecare cu timpul de preparare, caloriile pe porție și câte grame cântărește o porție. Atinge o rețetă ca s-o deschizi, iar „Salvează în Rețetele Mele” îți face propria copie, pe care o poți modifica. Etichetele de categorie filtrează, iar o nouă atingere pe aceeași etichetă arată tot.",
    faq_a_recipe_grams: "În rețetă, lângă calorii, scrie „1 porție ≈ X g”. La rețetele tale, completează „Grame pe porție” (și timpul de preparare, dacă vrei) în formularul rețetei: amândouă sunt opționale, iar timpul apare pe banda colorată a rețetei.",
