    faq_a_recipe_scan_multi: "Da. În „Adaugă Rețetă”, atinge 📷 și alege una sau mai multe fotografii (până la 6; merge și un PDF). Fiecare apare într-o listă scurtă unde alegi ce conține: Tot, Ingrediente sau Preparare, iar „➕ Încă o fotografie” mai adaugă. Apoi atinge „✨ Scanează rețeta”: AI-ul pune totul laolaltă într-o singură rețetă, în ordine și fără rânduri repetate, și se socotește o singură scanare. Și mai multe fotografii alese din 📷 Fotografie în asistentul AI se deschid aici.",
    faq_q_recipe_scan_multi: "Pot scana o rețetă din mai multe fotografii, de exemplu ingredientele și pașii separat, sau două pagini?",
