    faq_a_note_written_at: "Atinge textul notiței ca s-o deschizi. Înăuntru, sub text, apare când a fost scrisă ultima dată, cu data și ora exacte. Doar o schimbare a textului o actualizează: arhivarea și restaurarea, bifarea ✓, culorile sau mutarea notiței nu o schimbă.",
