    note_written_at: "Scrisă ultima dată: {date}",
    faq_a_new_me_month: "În rucsacul fermecat → Calendar lunar: fiecare zi e colorată după câte mese au fost bifate, săgețile ‹ › trec de la o lună la alta, iar sub calendar apare media zilnică a caloriilor din luna respectivă. O atingere pe o zi arată câte mese au fost bifate și câte calorii s-au mâncat în acea zi.",
    faq_q_new_me_month: "Unde văd luna în urmă și media caloriilor în New Me?",
    nm_month_avg: "Media lunii: {kcal} calorii pe zi · zile înregistrate: {n}",
    nm_month_day_empty: "În ziua aceasta nu s-a notat nimic.",
    nm_month_day_line: "Mese bifate: {checks} · calorii: {kcal}",
    nm_extra_line_small: "{n} calorii pentru masa aceasta, din micul dejun mic – de exemplu {ideas}",
    faq_a_new_me_small_breakfast: "Un mic dejun ușor (aproximativ 170 kcal): o pita din spelt (până la 100 kcal) cu cremă tartinabilă sau brânză, și o legumă – alege până la 3 care îți plac, de exemplu 1 linguriță de cremă de ciocolată, 1 linguriță de unt de arahide sau o felie de cașcaval (până la 22%). Fiindcă e mic, vine împreună cu „Plus o masă mică” la altă oră (o oră și jumătate mai târziu, de exemplu 11:30 → 13:00 – se poate alege orice altă oră): încă o pita cu cremă, iaurt proteic și fruct, rondele de orez cu brânză, cereale cu lapte sau jumătate de pita și ouă – până la aproximativ 200 kcal, cu propriul ✓. Ce mai rămâne se împarte între celelalte mese, iar fiecare masă arată cât i s-a adăugat, așa că totalul zilei rămâne ca în plan. Îl poți alege în chestionar sau poți trece la el doar pentru azi cu 🔄 – de exemplu, când micul dejun e târziu.",
