    faq_a_ai_icon: "Da – în Setări > Aspect și afișaj. Bula moale e cea implicită, iar cu Premium poți alege și un creier plutitor sau un robot.",
    faq_a_new_me_favorites: "Da. În chestionar (și când îl refaci din setări) poți alege până la 2 opțiuni pentru fiecare masă. Prima apare în meniu, cu un rând „sau” dedesubt pentru a doua – o atingere pe el trece la ea doar pentru azi. Iar dacă micul dejun n-a fost mâncat la timp, „⏰ Mai târziu” îl mută mai târziu în cursul zilei, fără să schimbe caloriile.",
    faq_a_theme_mode: "Unele teme speciale arată cel mai frumos întunecat – Acuarelă, Aurora boreală, Barbie și cele două teme cu sclipici –, așa că alegerea uneia dintre ele trece aplicația în modul întunecat, iar alegerea oricărei alte teme (și a rachetei) o trece pe luminos. Negru și Gri închis rămân întunecate. Poți oricând schimba apoi cu 🌙 din meniu sau cu Mod Luminos din setări.",
    faq_a_water_month: "În urmărirea apei. Fiecare intrare din înregistrarea de azi arată ora la care a fost adăugată, iar „Tabel lunar” deschide toată luna: fiecare zi arată câți litri s-au băut (✓ când s-a atins obiectivul zilnic), iar o atingere pe o zi arată intrările ei cu orele.",
