    room_reveal_star: "O stea nouă s-a aprins în telescopul de pe acoperiș ✨",
    faq_a_room_records: "Pick-up-ul e în cameră de la început, pe buturuga de lângă fotoliu. Discurile lui deschid pe YouTube clipurile oficiale ale unor mari hituri din ultimii ani, iar dedesubt sunt cinci melodii liniștite care cântă chiar aici în cameră – discul se învârte cât timp cântă, iar „⏹ Oprește” oprește muzica.",
    faq_a_room_roof_gifts: "Vin cu a 8-a cheie. O atingere pe telescop te lasă să te uiți prin el: cerul nopții de aproape (trage, sau folosește săgețile, ca să privești în jur), iar provocările încheiate desenează în el o constelație, câte o stea pentru fiecare provocare; o atingere pe o stea arată care a fost. O atingere pe cufărul mic îl deschide (deocamdată e gol) și încă o atingere îl închide.",
