    room_sand_erase_aria: "Freacă pentru a șterge scrisul",
    faq_a_home_note_line: "Scrie pe rândul din mijlocul ecranului principal și atinge ➤ (sau Enter) – se salvează în Notițe. Atinge 📝 de la începutul rândului și devine 🛒: atunci ce scrii ajunge în Lista de Cumpărături. Mai atinge o dată pentru 🍎: scrie câteva litere, apar mesele tale salvate care se potrivesc, iar o atingere notează una la mesele de azi. Cu 🎤 poți pur și simplu să spui.",
    faq_a_night_mode: "Deschide meniul ☰ și atinge 🌙 sus – toată aplicația devine întunecată. ☀️ din același loc aduce ziua înapoi. Este și în Setări, la Mod Luminos.",
