    menu_day_mode: "Mod zi",
    menu_night_mode: "Mod noapte",
    faq_a_secret_room_yoga: "La capătul potecii din pădure e o poartă luminoasă. În spatele ei, lângă o cascadă, făpturile pădurii – Lumi, Puffi, Nixie și Sparklet – stau pe saltelele lor, în semicerc, iar Flora, profesoara de yoga, stă în fața lor pe singura saltea de pe piatră. Atinge-o pe Flora: ea deschide ochii, totul se apropie și discuția începe încet, cu timp de citit – Flora întreabă ce face toată lumea, fiecare făptură răspunde în nume propriu (cu un mic desen al celui care vorbește lângă fiecare rând), apoi te întreabă cum te simți cu oamenii apropiați. Discuția continuă după răspunsurile tale – oameni buni, cineva cu care e greu sau puțină singurătate. Fiecare drum se termină cu o mică misiune (poate merge direct în Ziua Mea; când misiunea e să scrii ceva, există un loc unde să scrii, iar textul se salvează în jurnalul fermecat) și o postură cu trei respirații împreună. ↩ revine un pas, iar ✦ începe o discuție nouă. Următoarea cheie deschide cascada: când stai pe piatră, totul dispare și rămâne doar sunetul apei. Când te apleci peste iaz, din apă se ridică o întrebare – ce ar face azi adevăratul tău eu? – iar răspunsul devine o mică sarcină în Ziua Mea. E un moment blând, nu un înlocuitor pentru o discuție cu un specialist.",
    faq_q_secret_room_yoga: "Ce se întâmplă la yoga din pădure?",
    room_back_to_forest: "Înapoi pe potecă",
    room_back_to_yoga: "Înapoi la yoga",
    room_item_waterfall: "Cascada",
    room_waterfall_pool_aria: "Atinge apa",
    room_waterfall_rock_aria: "Stai pe stâncă",
    room_yoga_guide_aria: "Vorbește cu Flora",
    yg_g_alone: "Mulțumesc că ai împărtășit. Li se întâmplă tuturor uneori.",
    yg_g_alone_q: "Ce ți-ar prinde bine, măcar puțin?",
    yg_g_critic: "O critică poate înțepa mult timp. Vorbește despre un moment – nu despre tot omul.",
    yg_g_end: "Mulțumesc pentru acest moment în cerc. Poți reveni oricând vrei.",
    yg_g_gate: "Ai voie să pui o limită. O limită nu e un zid – e o poartă.",
    yg_g_good: "Ce frumos 💛 Cine ți-a făcut bine săptămâna asta?",
    yg_g_good_msg: "Oamenilor buni merită să le-o spui. Un mic mulțumesc le poate face toată ziua.",
    yg_g_hard: "Mulțumesc că ai spus-o. Ce apasă cel mai tare?",
    yg_g_listen: "Când nimeni nu te ascultă, obosești. Vocea ta contează, chiar și când e încetă.",
    yg_g_new: "Oamenii noi încep cu un mic salut. Un curs, o plimbare, un grup – un pas.",
    yg_g_old: "Cineva care te cunoaște deja e un loc cald. Un mesaj scurt e de ajuns.",
    yg_g_start: "Și acum e rândul tău 🌿 Cum te simți în ultima vreme cu oamenii apropiați?",
    yg_g_used: "Când dăm și nu primim nimic, ceva din noi obosește. E în regulă să observi asta.",
