    yg_pose_child: "Acum postura copilului 🌙 Genunchii jos, fruntea pe saltea – un loc sigur pentru respirat. Trei respirații împreună.",
    yg_pose_heart: "Acum inimă deschisă 💗 Umerii pe spate, pieptul larg. Trei respirații împreună.",
    yg_pose_tree: "Acum postura copacului 🌳 În picioare, stabil, o talpă pe celălalt picior, mâinile sus. Trei respirații împreună.",
    yg_task_good: "Să trimit azi un mic mesaj de mulțumire",
