    nm_time_hour: "Ora",
    nm_time_minutes: "Minute",
    routine_time_taken: "La ora aceasta există deja ceva: {title}",
    faq_a_new_me_times: "În chestionarul de la început și oricând în setările New Me → „Orele meselor”. Dacă rutina ta are deja ore pentru mese, ele sunt preluate de acolo – iar mesele din rutină pot fi ascunse, cu mesele New Me în locul lor. Dacă nu, alegi câte mese pe zi (2 mese + o gustare / 2 mese + o cină ușoară / 2 mese + o gustare + o cină ușoară) și când e fiecare. La „2 mese + o gustare” sunt prânzul la 11:30, gustarea la 16:00 și cina la 19:00 (oricare se poate schimba). Acestea sunt orele meselor tale peste tot: pe hol, în Ziua Mea, în Rutina Mea și în mementouri. Orice ai alege, caloriile zilei rămân aceleași: ce se scoate se împarte între celelalte mese.",
    faq_q_new_me_times: "Cum îmi stabilesc orele meselor în New Me?",
    nm_times_count: "Câte mese pe zi?",
    nm_times_from_routine: "Da, ia-le din rutina mea",
    nm_times_hide: "Ascunde mesele din rutina mea și arată în locul lor mesele New Me",
    nm_times_later: "Mai târziu",
    nm_times_manual: "Nu, aleg aici",
    nm_times_none_found: "Rutina ta nu are încă mese – alege aici câte și când.",
    nm_times_q: "Rutina ta are ore fixe pentru mâncat?",
    nm_times_saved: "Orele meselor au fost salvate",
    nm_times_title: "Orele meselor",
    faq_a_routine_exact_time: "Da. Când descrii AI-ului o rutină cu o oră exactă (de exemplu „16:10 trading”), ea se salvează exact așa – fără rotunjire la ora fixă. Tot ce e scris în rutină apare mereu pe panou, chiar dacă ora respectivă nu e aleasă în setările orelor, iar eliminarea unei ore în care e ceva scris cere mai întâi confirmare. Poți schimba și manual o oră: atinge ora în fereastra elementului și alege ora și minutele.",
    faq_q_routine_exact_time: "Poate rutina mea să aibă o oră exactă, cum ar fi 16:10?",
    room_item_sand: "Scris în nisip",
    room_item_yoga: "Yoga în pădure",
    room_sand_ph: "Ce ai vrea să lași să plece?",
    room_sand_write: "Scrie",
