    routine_daysoff_what: "Și care e rutina în zilele acelea?",
    routine_daysoff_which: "Ce zile?",
    faq_a_secret_room_diary: "Doar tu. Paginile jurnalului se salvează în cont, așa că sunt pe orice dispozitiv și nimeni altcineva nu le vede. Jurnalul fermecat de pe biroul din camera secretă îl deschide, la fel și jurnalul din colțul muzicii. Sub pagina nouă e un tabel lunar pliat: un punct marchează fiecare zi care are o pagină, iar atingerea unei zile îi deschide paginile – acolo se poate și șterge o pagină. Când jurnalul e deja deschis, poate fi adăugat și în meniul principal – cu comutatorul din jurnalul însuși sau din setările New Me.",
    faq_a_secret_room_places: "Fiecare intrare de la poarta pădurii se deschide cu cheia ei. În spatele lor: veranda cu vedere la mare (pe măsuța mică lampa lui Aladin – o atingere, și un spirit al pădurii se înalță din ea într-o ceață fermecată, se rotește în jur și începe o conversație despre dorința ta – vezi „Ce face duhul lămpii?”), chitara și jurnalul (chitara cântă o melodie scurtă și liniștită și se oprește singură, iar fiecare dintre cele trei discuri care atârnă în copac cântă propria melodie fermecată – încă o atingere o oprește – iar în jurnalul de pe buturugă se scrie), camera respirației (un lac liniștit la apus – pe apă plutește un felinar de lotus: atinge-l, scrie o dorință, și se îndepărtează odată cu ea, departe în adâncul lacului; cu bagheta magică poți scrie în nisip ce vrei să lași să plece, și rămâne acolo până îl ștergi cu degetul) și poteca din pădure (se deschide noaptea, iar atingerea felinarelor o schimbă în zi; pe bancă se poate sta, iar atingerea plăcuței o aduce aproape – o tablă cu șase întrebări mici de bifat). Pe o intrare încuiată se vede câte chei mai lipsesc. La capătul potecii, o poartă luminoasă duce la yoga de lângă cascadă – și de acolo, la cascada însăși.",
    faq_q_secret_room_diary: "Cine vede jurnalul?",
