    ai_chat_working_table: "O clipă, fac tabelul…",
    dev_weather_preview_label: "Previzualizare – doar în contul tău:",
    faq_a_ai_chat: "Atinge bula și se deschide un chat. Alege ce vrei să faci – ceva pentru calendar, ce ai mâncat, poza unei rețete sau un tabel nou – sau pur și simplu scrie, iar asistentul înțelege ce trebuie. Poți și să atingi 🎙️ și să vorbești în loc să scrii. Pentru calendar poți alege o dată, în fiecare săptămână sau în fiecare zi. Răspunsul vine în chat, iar de acolo poți trece la altceva sau poți deschide calendarul / ce ai mâncat.",
    faq_a_new_me_hall: "New Me se deschide la poarta unei păduri fermecate, iar fiecare intrare de acolo e un loc: ușa rotundă din copacul uriaș duce în camera secretă, bușteanul scorburos – la veranda cu vedere la mare, căsuța-ciupercă – la chitara și jurnalul, arcada mică de salcie – la camera respirației, arcada mare de salcie – la poteca din pădure, iar arcada de flori cu scara urcă pe acoperișul stelelor când acesta se deschide. Pe o intrare încuiată se vede un lacăt. Deasupra potecii plutește personajul tău, Sky, iar de jur împrejur sunt butoanele jocului: următoarea misiune, provocarea săptămânii, rucsacul fermecat cu tot New Me, harta lumii și uneltele. O atingere pe cheile de sus explică cum se câștigă cheile.",
    faq_a_new_me_routine_meals: "Când sunt setate mese în New Me și Rutina Mea are și ea mese, New Me întreabă dacă să le ascundă și să arate în locul lor mesele New Me – ca nimic să nu apară de două ori. Atunci Rutina Mea arată mesele New Me la orele lor, cu 💎 și un ✓; o atingere pe numele unei mese deschide o fereastră pentru a alege altă masă sau a-i schimba ora, chiar acolo, peste rutină. Nu se șterge nimic: revin din ⚙️ Setările New Me → Mese în rutină sau prin oprirea „Sincronizare cu New Me” în ⚙️ din Rutina Mea. Fără un New Me activ, revin de la sine.",
    faq_a_room_computer: "E un mic chat care începe cu „Cum îți merge ziua până acum?” – bine, aglomerat sau greu – și continuă cu tine pas cu pas, până la o mică misiune la final (care poate merge și direct în Ziua Mea). Răspunsurile pot fi atinse sau scrise liber – ce se scrie se leagă de cel mai apropiat răspuns. „↩ Înapoi” revine cu un pas ca să poți răspunde altfel, iar „Chat nou” o ia de la capăt oricând. După o zi aglomerată sau grea poți reveni la calculator mai târziu în aceeași zi: „Am revenit...” continuă conversația. Lumina verde de jos stinge și aprinde calculatorul. Se păstrează doar alegerile, doar pe acest dispozitiv și doar până la sfârșitul zilei.",
    faq_q_ai_chat: "Cum vorbesc cu asistentul?",
