    dictation_btn_aria: "Vorbește și se scrie",
    dictation_mic_denied: "Microfonul e blocat – permite-l din 🔒 de lângă adresă în browser sau din setările telefonului",
    faq_a_dictation: "Da – atinge microfonul 🎤 din colțul notiței rapide sau al unei pagini de scris din caiet și vorbește: cuvintele se scriu pe măsură ce vorbești, în limba aplicației. Atinge din nou pentru a opri. Prima dată, browserul cere permisiunea de a folosi microfonul. Funcționează în Chrome / Android și în Safari pe iPhone. Pe calculator ai nevoie de un microfon și de un browser ca Chrome, Edge sau Safari – dacă lipsește ceva, mesajul spune exact ce.",
    faq_q_dictation: "Pot vorbi în loc să scriu?",
    faq_a_secret_room: "O cameră doar a ta, în New Me – o casă în interiorul unui copac uriaș. Vezi câte un perete și te întorci cu săgețile (sau glisând). Prima cheie vine după un ✓ la o masă în 3 zile diferite și deschide ușa – și odată cu ea toată camera: calculatorul, jocul, pick-up-ul, raftul cu biblioteca înăuntru și pisica. Apoi fiecare provocare încheiată (inclusiv provocarea săptămânii) dă o cheie care deschide locul următor: acoperișul stelelor, veranda cu vedere la mare, chitara și jurnalul, camera respirației, poteca din pădure cu yoga, cascada și o surpriză pe acoperiș – iar a 8-a aduce o sticlă din mare, cu scrisoarea din trecut înăuntru. Când se deschide ceva, o săgeată arată drumul. Se deschide și ușița de jos a aparatului de joc – deocamdată dulapul din spatele ei e gol. Pe acoperișul stelelor, o stea atinsă cade ca o stea căzătoare, iar pisica stă pe pernă.",
