    home_countdown_tomorrow: "Mâine · {title}",
    home_streak_days: "{n} zile la rând",
    home_streak_title: "Zile la rând cu cel puțin o ✓",
    settings_good_things_label: "„3 lucruri bune” seara",
    settings_weather_hint: "Ploaie, nori sau zăpadă pe fundalul ecranului principal, după vremea de unde ești. Locația ta aproximativă rămâne pe acest dispozitiv și e verificată prin serverul nostru la MET Norway.",
    settings_weather_label: "Vremea pe cerul ecranului principal",
    weather_failed: "Momentan nu am putut verifica vremea.",
    weather_location_denied: "Nu există acces la locație – permite-l din setările browserului și încearcă din nou.",
    faq_a_home_focus: "Atinge ◎ în partea de sus a ecranului principal: dispare totul în afară de singurul lucru de acum – ce e la ora asta sau următorul din lista de azi – cu o ✓ mare, plus Notițe Rapide. După ✓ apare următorul lucru. Atinge „Modul concentrare ✕” sus ca să revină totul.",
    faq_a_home_search: "Deschide meniul ☰ – căutarea e chiar sus. Scrie cel puțin 2 litere: rezultatele vin din notițe, lista de cumpărături, calendar, rețete, caiete (titluri și textul paginilor), obiective, tabele și cărți, grupate pe tipuri – atinge unul ca să ajungi direct acolo.",
    faq_a_my_day: "Ziua Mea adună ce era înainte O Privire Asupra Zilei de Azi și Rutina Mea, pe o singură linie a timpului. În partea de jos a ecranului principal vezi cât e gata, ce e acum sau urmează (cu o ✓ rapidă) și, lângă titlu, un pahar cu apă cu +1. Atinge-o (sau glisează în sus) ca să deschizi toată ziua: sus ce nu are oră, apoi totul pe ore – sarcini, evenimente și întâlniri din calendar, intervalele fixe săptămânale, rutina de azi, pașii mici ai obiectivelor tale și mesele New Me – cu o linie pentru acum. Filtrează după Sarcini, Rutină sau Întâlniri și evenimente. O ✓ aici e aceeași ✓ de peste tot (Rutina Mea, Obiectivele Mele, calendarul) și deschide o margaretă în colț. „Editează rutina” deschide Rutina Mea (e și în meniu), iar „＋ Adaugă pentru azi” adaugă o sarcină pentru azi. O atingere pe titlul „Ziua Mea” (sau pe bara mică de sus) îl închide din nou.",
    faq_q_home_focus: "Ce este modul concentrare?",
    faq_q_home_search: "Cum caut în toată aplicația?",
