    faq_a_table_shopping_link: "Într-o coloană ✓ legată de lista de cumpărături (cum e „Avem ingrediente” din „Mesele săptămânii”), fiecare rând încă nebifat are un 🛒. O atingere îl adaugă în lista de cumpărături – o singură dată, niciodată dublu. Bifează-l aici ✓ și iese din listă; șterge-l din listă și aici nu mai apare „în listă”; marchează-l în listă drept cumpărat și rândul de aici primește ✓ singur. Orice coloană ✓ poate fi legată sau dezlegată din setările coloanei.",
