    faq_a_new_me_tour: "Imediat după cumpărare și completarea chestionarului scurt, un tur scurt arată jocul: bara de sus, următoarea misiune, provocarea săptămânii, rucsacul fermecat și ușa 1 spre camera secretă. Poate fi revăzut oricând din ⚙️ Setări > 🧭 Turul New Me – tot acolo se poate schimba și numele complet din chestionar. Înainte de cumpărare, New Me arată un 🔒 în meniu, iar atingerea lui deschide o pagină cu tot ce este inclus.",
