    nm_gift_title: "Cadoul tău",
    faq_a_new_me_letter_gift: "La începutul New Me (sau mai târziu, în Provocări) se poate scrie o scrisoare pentru tine în viitor. Odată sigilată, nu mai poate fi citită sau editată până nu se deschide: în sticla din mare din camera secretă sau la finalul tuturor celor 20 de provocări – unde te așteaptă și un cadou.",
    faq_q_new_me_letter_gift: "Ce este scrisoarea din trecut?",
    faq_a_new_me_challenges: "🏆 Provocări are 20 de provocări: 10 mari (de exemplu 5 zile fără zahăr, o săptămână fără carbohidrați sau minus 4 kg într-o lună – în fiecare zi deficit caloric, antrenament și fără zahăr) și 10 mini – obiceiuri mici pentru o săptămână, ca o cafea cu scorțișoară fără zahăr. La alegerea unei provocări apare întrebarea când să înceapă: azi, mâine, săptămâna viitoare sau la altă dată. O provocare mare și o mini provocare pot merge în paralel. Provocarea în curs apare în capul meniului și în Ziua Mea, cu un ✓ pentru ziua respectivă. Fiecare săptămână de provocare aduce o zi liberă (🍕) care nu o întrerupe, iar o zi nebifată contează ca zi liberă – se pot bifa ziua de azi și cea de ieri. Unele zile se bifează singure: un antrenament de 20 de minute în Urmărire Antrenamente sau mesele din meniu cu ✓. Fiecare provocare are un ⓘ cu ce contează exact (de exemplu, lista completă a carbohidraților) – în provocarea însăși și lângă ea, în Ziua Mea. Sub ele, 🌱 Dezvoltare personală are 48 de provocări mici pentru o săptămână (nu se numără la cele 20) – vezi „Ce este provocarea săptămânii?”.",
    faq_q_new_me_challenges: "Cum funcționează provocările din New Me?",
