    faq_a_workout_calories: "Da. Fiecare antrenament primește o estimare a caloriilor arse – după tip, durată și ultima ta greutate (la alergare și ciclism și după viteză, dacă e introdusă distanța). Apare în lista de antrenamente și în rezumatul lunar (Arse) și se adaugă la bugetul de calorii al acelei zile: în Jurnalul Zilnic de Alimentație, în Statistici Calorii și Greutate și în inelul New Me. E o estimare, de aceea apare cu ~.",
    faq_q_workout_calories: "Antrenamentele contează la caloriile zilei?",
    faq_a_new_me_flexible_menu: "Da. În chestionar și în setări alegi câte mese pe zi – 2 mese + o gustare / 2 mese + o cină ușoară / 2 mese + o gustare + o cină ușoară – iar ➖ pe cardul unei mese o scoate (rămân cel puțin 3); „Pune înapoi” o readuce. Oricum ar fi, caloriile zilei rămân aceleași: ce se scoate se împarte între celelalte mese, iar sub fiecare masă scrie cât s-a adăugat și ce se potrivește. ✏️ Editează pe o masă îi deschide textul – schimbă ce vrei (ex.: fără pâine sau cu încă un ou) și AI recalculează caloriile și proteinele. 🔄 Schimbă oferă opțiuni din meniu, ⭐ Salvate și ✨ Scrie-o; fiecare schimbare poate fi doar pentru azi sau de acum înainte. Iar la finalul „Toată ziua” există ➕ Adaugă mâncare – scrie ce s-a mâncat în afara meniului, iar AI calculează și adaugă la azi (✕ șterge).",
