    books_menu_label: "Colțul de lectură",
    faq_a_goal_tasks_peek: "Trei tipuri: sarcinile zilnice dintr-o provocare pe zile activă (de exemplu 'Fără carbohidrați') – apar în fiecare zi până când provocarea se încheie, iar un ✓ acolo bifează ziua în obiectiv (și invers); 📅 reperele programate ale obiectivelor tale – la data lor, și totodată în calendar; și 👣 pasul mic al oricărui alt obiectiv – îl stabilești când adaugi sau editezi obiectivul (în fiecare zi sau în fiecare săptămână, într-o zi aleasă de tine). Sunt aceiași pași ca în 'Pașii mici de azi', sus în Obiectivele Mele, fiecare cu pictograma obiectivului său. Un +1 înregistrat în ziua respectivă bifează automat pasul mic (la fel și o cântărire, când pasul mic este chiar cântărirea).",
