    vision_tagline: "Obiective mari, pași mici.",
    faq_a_app_tour: "Turul se deschide singur o dată, la prima intrare. Începe cu părțile sale – atinge una ca să ajungi direct acolo – apoi arată fiecare parte a aplicației (ecranul principal, asistentul AI și fiecare element din meniu) și cele cinci grupuri de Setări, fiecare cu o scurtă explicație, și aruncă o privire în interiorul unora (de exemplu un traseu demonstrativ al unui obiectiv, rucsacul și Google Calendar). Continuă merge înainte, Înapoi se întoarce, Sari peste această parte trece la partea următoare, iar ✕ închide turul. Îl poți revedea oricând din Setări > Ajutor și utilizare > Tur al aplicației și poți continua de unde ai rămas. Continuă și Înapoi rămân mereu în același loc, în partea de jos a ecranului, iar pe calculator merg și săgețile de pe tastatură.",
