    nm_drink_name_ph: "Băutură (ex. suc)",
    nm_drinks_hint: "Scrie doar băutura – caloriile se calculează automat, iar numărul poate fi modificat.",
    nm_slot_drinks: "Băuturi",
    faq_a_new_me_tracking: "Atinge următoarea misiune din partea de sus a New Me și apoi ✓ Am mâncat ca să marchezi următoarea masă ca mâncată – tot meniul cu ✓ la fiecare masă e în Toată ziua, pe lateral, iar mesele de azi apar și în Ziua Mea pe ecranul principal – o atingere pe una dintre ele acolo (sau mouse-ul deasupra) arată exact ce e de mâncat, cu ✓ și Schimbă. Totul se sincronizează cu Jurnalul Zilnic de Alimentație: mesele din plan, băuturile și orice adaugi în altă parte (de exemplu o cafea din adăugarea rapidă) se numără împreună în New Me și în Ziua Mea – nimic din ce ai scris deja nu se suprascrie, iar eliminarea unui ✓ elimină doar partea New Me. Când toate mesele de azi sunt bifate, urmează o mică sărbătoare. La „Băuturi” se notează băuturile zilei – toate împreună până la ~150 kcal, adică aproximativ 3 băuturi de până la ~50 kcal fiecare. Ajunge să scrii numele băuturii, iar caloriile se completează automat cu AI. Cele două rânduri de cafea/ceai au și un câmp „Lapte? Cât?” (de exemplu „puțin” sau „50 ml”), iar calculul se actualizează; numărul poate fi schimbat înainte de adăugare și după. O băutură cu nume și calorii se salvează automat imediat ce treci mai departe – atingerea butonului Adaugă e opțională. Atinge ☆ lângă o băutură ca s-o salvezi ca băutură obișnuită – băuturile obișnuite apar ca butoane în partea de sus a cardului Băuturi, iar o atingere le adaugă la zi. ⭐ salvează o masă ca masă salvată. „Tabel zilnic” arată ce ai mâncat, cu calorii și proteine. Micul 💎 de lângă modul concentrare, sus pe ecranul principal, îl deschide direct. Valorile de calorii și proteine sunt estimări AI și pot conține erori. N-ai mâncat tot? Sub o masă bifată, „N-am mâncat tot?” scade un sfert, jumătate sau trei sferturi din porție – sau ce scrii tu, calculat – iar caloriile zilei se actualizează.",
    faq_q_new_me_tracking: "Cum funcționează ✓, schimbările și caloriile în New Me?",
    faq_a_new_me_what: "New Me este un program separat de meniu zilnic, cu două planuri gata făcute – 1.300 sau 1.500 de calorii – din 2 mese principale și 2 gustări, cu câte 3 opțiuni pentru fiecare. Include tot Premium. Preț: $11.99 pe lună (anulezi oricând) sau $99.99 o singură dată, pe viață. Se deschide din 💎 New Me din meniu. Înainte de început există un chestionar scurt care începe cu o declarație medicală ce trebuie acceptată. Programul este doar informație generală și nu înlocuiește un medic sau un dietetician clinic.",
