    daily_focus_modal_title: "🧠 Care e cel mai important lucru pe care trebuie să-l faci azi?", daily_focus_modal_subtitle: "Răspunde, și se va adăuga direct în programul de azi.", daily_focus_input_placeholder: "Azi îmi doresc cel mai mult să", daily_focus_save_btn: "Adaugă în programul de azi", daily_focus_skip_btn: "Nu acum", daily_focus_missing_text: "Scrie ceva mai întâi", daily_focus_added_toast: "Adăugat în programul de azi", daily_focus_other_option: "✍️ Altceva...",
    daily_focus_c1_d0: "Să-mi protejez spațiul de liniște de zgomotul din jur", daily_focus_c1_d1: "Să pun limite clare, cu iubire și fără vinovăție", daily_focus_c1_d2: "Să rămân ancorat/ă chiar și atunci când e furtună în jurul meu", daily_focus_c1_d3: "Să pun calmul și energia mea pe primul loc", daily_focus_c1_d4: "Să nu preiau sentimentele și stările celorlalți", daily_focus_c1_d5: "Să nu las cuvintele altora să-mi clatine valoarea de sine",
    daily_focus_c2_d0: "Să ascult ce au nevoie corpul și mintea mea", daily_focus_c2_d1: "Să mă bucur de lucrurile mici de pe parcurs", daily_focus_c2_d2: "Să încetinesc și să mă conectez cu adevărat cu mine", daily_focus_c2_d3: "Să-mi ofer spațiu să respir în mijlocul acțiunii", daily_focus_c2_d4: "Să mă simt acasă și în pace cu mine însumi/însămi", daily_focus_c2_d5: "Să mă concentrez pe ce se întâmplă acum, fără să mă grăbesc înainte",
    daily_focus_c3_d0: "Să-mi păstrez cuvintele încurajatoare, răbdătoare și înțelegătoare", daily_focus_c3_d1: "Să nu iau nimic personal", daily_focus_c3_d2: "Să nu presupun - ci doar să întreb, sau să las de la mine", daily_focus_c3_d3: "Să am încredere în ritmul și drumul meu", daily_focus_c3_d4: "Să renunț la perfecțiune și să aleg progresul", daily_focus_c3_d5: "Să fiu răbdător/oare cu propriul meu proces",
    daily_focus_c4_d0: "Să termin ziua simțindu-mă mândru/ă și împlinit/ă", daily_focus_c4_d1: "Să-mi observ progresul, chiar și în pași mici", daily_focus_c4_d2: "Să mă concentrez pe o singură sarcină odată", daily_focus_c4_d3: "Să pun ordine în sarcinile mele și să acționez calm", daily_focus_c4_d4: "Să mă accept exact așa cum sunt astăzi", daily_focus_c4_d5: "Să știu când să acționez și când să las de la mine",
    daily_focus_c5_d0: "Să aduc zâmbet și ușurință în tot ce fac", daily_focus_c5_d1: "Să încep ziua cu energie proaspătă și bună", daily_focus_c5_d2: "Să-mi ofer o zi liniștită, fără așteptări apăsătoare", daily_focus_c5_d3: "Să aduc bucurie simplă în rutina mea", daily_focus_c5_d4: "Să-mi deschid inima la surprize bune astăzi", daily_focus_c5_d5: "Să încep ziua cu recunoștință și un zâmbet",
    daily_focus_c6_d0: "Să ascult cu adevărat, nu doar să-mi aștept rândul să vorbesc", daily_focus_c6_d1: "Să-mi amintesc că fiecare duce ceva ce nu se vede", daily_focus_c6_d2: "Să răspândesc energie caldă și primitoare în jurul meu", daily_focus_c6_d3: "Să păstrez deschidere și respect în felul în care comunic", daily_focus_c6_d4: "Să văd binele din oamenii din jurul meu", daily_focus_c6_d5: "Să ofer un cuvânt bun cuiva care are nevoie de el azi",
