    daily_focus_p6_d6_s1: "Să fac loc, cu respect, pentru sărbătorirea personală și odihna binemeritată", daily_focus_p6_d6_s2: "Să rezum tot anul cu recunoștință, forță și o satisfacție profundă", daily_focus_p6_d6_s3: "Să privesc înainte cu curiozitate, încredere și dragoste pentru drum", daily_focus_p6_d6_s4: "Să las totul să plece într-o liniște adâncă, știind că am dat tot ce am putut", daily_focus_p6_d6_s5: "Să mă umplu de energie nouă și proaspătă pentru următorul ciclu",
    daily_focus_p6_d7_s1: "Să dedic ziua sărbătoririi vieții, liniștii și unei recunoștințe profunde", daily_focus_p6_d7_s2: "Să ascult liniștea interioară dintr-un loc de plenitudine și satisfacție deplină", daily_focus_p6_d7_s3: "Să mă apreciez pentru un an întreg de creștere, curaj și succes", daily_focus_p6_d7_s4: "Să las totul deoparte și să mă bucur de o prezență curată și senină", daily_focus_p6_d7_s5: "Să mulțumesc pentru persoana care am devenit de-a lungul acestui drum",
    faq_q_daily_focus_prompt: "Ce este mementoul mic care mă întreabă ce e cel mai important de făcut azi?", faq_a_daily_focus_prompt: "Este un memento zilnic Premium: o dată pe zi apare o insignă mică „1” pe pictograma asistentului AI. Atinge insigna ca să deschizi o bulă care te întreabă ce contează cel mai mult pentru tine azi, în care apar imediat 5 sugestii gata făcute (se schimbă zilnic, trecând printr-un an întreg de teme diferite, ca să rămână proaspete) plus 'Altceva' ca să scrii propria variantă - poți alege mai multe. Atinge Adaugă, iar alegerile tale apar ca etichete mici de memento în partea de sus a 'Ziua Mea' (nu sunt sarcini de bifat). Dacă o închizi cu ✕ sau atingi în afara ei, insigna doar se estompează pentru restul zilei, în loc să dispară. Este activat implicit, dar îl poți dezactiva din Setări > Personalizare și calendar. Nu e ziua potrivită? Atinge '🌙 Nu azi' – insigna dispare până mâine, apoi întrebarea revine ca de obicei. Una dintre sugestii vine din propria ta viață – următorul pas al obiectivului lunii sau lectura de azi. Fiecare zi începe de la capăt.",
